mapper.select:
SELECT CAST(p.record_id AS CHAR) recordId,CAST(p.post_id AS CHAR) postId,CAST(p.binding_id AS CHAR) bindingId,
CAST(p.place_id AS CHAR) placeId,p.post_name postName,p.place_name placeName,p.device_code deviceCode,p.device_name deviceName,
p.inspector_name inspectorName,DATE_FORMAT(p.inspect_time,'%Y-%m-%d %H:%i:%s') inspectTime,
p.result,p.note,(p.evidence_file IS NOT NULL) hasEvidence
FROM fire_inspection_record p WHERE 1=1
AND p.record_id=#{id}
AND p.post_id=#{postId}
AND (p.post_name LIKE CONCAT('%',#{keyword},'%') OR p.place_name LIKE CONCAT('%',#{keyword},'%') OR p.inspector_name LIKE CONCAT('%',#{keyword},'%'))
AND p.result=#{result}
AND p.inspect_time >= #{beginTime}
AND p.inspect_time < DATE_ADD(#{endTime},INTERVAL 1 DAY)
${params.dataScope}
ORDER BY p.inspect_time DESC,p.record_id DESC
